//! Lexer for the `lw-demo` language, generated by [`logos`].
//!
//! The public entry point is [`lex_file`], which produces a flat
//! [`CstArena`] (token ledger) and a [`LineIndex`] (newline positions).
//!
//! Every byte of the source is covered by exactly one token — whitespace,
//! comments, and errors are all emitted, so the token stream is lossless.

use logos::Logos;

use lw_cst::{CstArena, LineIndex, SyntaxToken};

// ---------------------------------------------------------------------------
// Token kind
// ---------------------------------------------------------------------------

/// Every kind of token the lexer can produce.
///
/// Variants annotated with `#[token(...)]` match exact strings; variants
/// annotated with `#[regex(...)]` match regular expressions.  The fallback
/// `Error` variant captures any unrecognised input so the lexer never panics.
#[derive(Logos, Debug, Clone, Copy, PartialEq, Eq)]
#[logos(error = ())]
pub enum TokenKind {
    // --- keywords ---
    #[token("let")]
    Let = 0,

    #[token("import")]
    Import = 1,

    // --- literals & names ---
    /// An integer literal: one or more ASCII digits.
    #[regex(r"[0-9]+")]
    IntLiteral = 2,

    /// A double-quoted string literal (no escape sequences needed for paths).
    #[regex(r#""[^"\n]*""#)]
    StringLiteral = 3,

    /// An identifier: starts with a letter or `_`, followed by alphanumerics
    /// or `_`.  Keywords are matched first, so they won't fall here.
    #[regex(r"[a-zA-Z_][a-zA-Z0-9_]*")]
    Ident = 4,

    // --- operators ---
    #[token("=")]
    Equals = 5,
    #[token("+")]
    Plus = 6,
    #[token("-")]
    Minus = 7,
    #[token("*")]
    Star = 8,
    #[token("/")]
    Slash = 9,

    // --- trivia ---
    /// One or more newline characters (`\n` or `\r\n`).
    #[regex(r"(\r\n|\n)+")]
    Newline = 10,

    /// One or more non-newline whitespace characters.
    #[regex(r"[^\S\n\r]+")]
    Whitespace = 11,

    /// A `// …` line comment (everything up to, but not including, the newline).
    // Excludes `\r` so CRLF line endings are handled cleanly.
    #[regex(r"//[^\n\r]*", allow_greedy = true)]
    Comment = 12,

    // --- sentinels ---
    /// Logical end of input (synthesised by [`lex_file`], never emitted by logos).
    Eof = 13,

    /// Unrecognised input — represented explicitly so the token stream is
    /// lossless; logos emits `Err(())` for any byte not matched above and we
    /// convert it here.
    Error = 14,
}

impl TokenKind {
    /// Convert to the `u16` representation stored in [`SyntaxToken`].
    pub fn to_u16(self) -> u16 {
        self as u16
    }

    /// Convert from a `u16` stored in [`SyntaxToken`].
    pub fn from_u16(raw: u16) -> Self {
        match raw {
            0 => Self::Let,
            1 => Self::Import,
            2 => Self::IntLiteral,
            3 => Self::StringLiteral,
            4 => Self::Ident,
            5 => Self::Equals,
            6 => Self::Plus,
            7 => Self::Minus,
            8 => Self::Star,
            9 => Self::Slash,
            10 => Self::Newline,
            11 => Self::Whitespace,
            12 => Self::Comment,
            13 => Self::Eof,
            _ => Self::Error,
        }
    }

    /// Whether this token is trivia (whitespace, newline, comment).
    pub fn is_trivia(self) -> bool {
        matches!(self, Self::Whitespace | Self::Newline | Self::Comment)
    }
}

// ---------------------------------------------------------------------------
// Public entry point
// ---------------------------------------------------------------------------

/// Lex `source` into a flat [`CstArena`] (token ledger) and a [`LineIndex`].
///
/// Every byte of `source` is covered by exactly one token — whitespace,
/// comments, and errors are all emitted rather than skipped.  The final
/// token is always [`TokenKind::Eof`] with zero byte length.
///
/// The [`LineIndex`] is built simultaneously by recording the byte offset
/// of every `\n` encountered during lexing.
pub fn lex_file(source: &str) -> (CstArena, LineIndex) {
    let mut tokens: Vec<SyntaxToken> = Vec::new();

    for (kind, span) in TokenKind::lexer(source).spanned() {
        let kind = kind.unwrap_or(TokenKind::Error);
        let len = (span.end - span.start) as u32;
        tokens.push(SyntaxToken {
            kind: kind.to_u16(),
            len,
        });
    }

    // Eof sentinel with zero byte length.
    tokens.push(SyntaxToken {
        kind: TokenKind::Eof.to_u16(),
        len: 0,
    });

    let arena = CstArena::from_tokens(source.to_string(), tokens);
    let line_index = LineIndex::from_source(source);

    (arena, line_index)
}

// ---------------------------------------------------------------------------
// Unit tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    /// Collect just the token kinds from a lex result (excluding Eof).
    fn kinds(source: &str) -> Vec<TokenKind> {
        let (arena, _) = lex_file(source);
        arena
            .tokens()
            .iter()
            .map(|t| TokenKind::from_u16(t.kind))
            .filter(|k| *k != TokenKind::Eof)
            .collect()
    }

    #[test]
    fn lex_let_binding() {
        let toks = kinds("let x = 1");
        assert_eq!(
            toks,
            vec![
                TokenKind::Let,
                TokenKind::Whitespace,
                TokenKind::Ident,
                TokenKind::Whitespace,
                TokenKind::Equals,
                TokenKind::Whitespace,
                TokenKind::IntLiteral,
            ]
        );
    }

    #[test]
    fn lex_import() {
        let toks = kinds("import \"math.lw\"");
        assert_eq!(
            toks,
            vec![
                TokenKind::Import,
                TokenKind::Whitespace,
                TokenKind::StringLiteral,
            ]
        );
    }

    #[test]
    fn lex_operators() {
        let toks = kinds("+-*/");
        assert_eq!(
            toks,
            vec![
                TokenKind::Plus,
                TokenKind::Minus,
                TokenKind::Star,
                TokenKind::Slash,
            ]
        );
    }

    #[test]
    fn lex_comment_and_newline() {
        let toks = kinds("// hello\nlet x = 1");
        assert_eq!(toks[0], TokenKind::Comment);
        assert_eq!(toks[1], TokenKind::Newline);
        assert_eq!(toks[2], TokenKind::Let);
    }

    #[test]
    fn lex_crlf_comment_does_not_consume_newline() {
        let toks = kinds("// hello\r\nlet");
        assert_eq!(toks[0], TokenKind::Comment);
        assert_eq!(toks[1], TokenKind::Newline);
        assert_eq!(toks[2], TokenKind::Let);
    }

    #[test]
    fn lex_every_byte_is_covered() {
        let source = "let x = 1 + 2\n";
        let (arena, _) = lex_file(source);
        let covered: u32 = arena
            .tokens()
            .iter()
            .filter(|t| TokenKind::from_u16(t.kind) != TokenKind::Eof)
            .map(|t| t.len)
            .sum();
        assert_eq!(covered, source.len() as u32, "lossless token coverage");
    }

    #[test]
    fn lex_unknown_char_produces_error() {
        let toks = kinds("@");
        assert_eq!(toks, vec![TokenKind::Error]);
    }

    #[test]
    fn lex_file_produces_line_index() {
        let (_, line_index) = lex_file("line one\nline two\nline three");
        assert_eq!(line_index.line_count(), 3);
        let pos = line_index.byte_to_lsp_position(14);
        assert_eq!(pos.line, 1);
    }
}
